def wse_function(paren_string: str) -> List[int]:
    """
    Input: a string containing groups of nested parentheses separated by spaces.
    Output: a list of integers representing the maximum nesting depth of parentheses for each group.

    The function does not use loops or recursion.
    """
    # Split the input string by spaces to get groups
    groups = paren_string.split()

    # Define a helper function using map and reduce to compute max depth without explicit loops or recursion
    from functools import reduce

    def max_depth(s: str) -> int:
        # For each character, map '(' to +1, ')' to -1, else 0 (though input is only parentheses)
        diffs = list(map(lambda c: 1 if c == '(' else -1, s))
        # Use reduce to track current depth and max depth
        # accumulator: (current_depth, max_depth)
        def reducer(acc, x):
            cur, mx = acc
            cur += x
            mx = max(mx, cur)
            return (cur, mx)
        _, maximum = reduce(reducer, diffs, (0, 0))
        return maximum

    # Map max_depth over all groups and return as list of ints
    return list(map(max_depth, groups))


