def wse_function(s):
    """
    Takes a string s and returns a string where each word's characters
    are sorted in ascending ASCII order, preserving the exact spacing
    (all spaces and their positions) between words.
    Words are sequences of characters separated by spaces (space character only).
    Other whitespace characters inside words are not treated specially.
    """
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == ' ':
            # accumulate all consecutive spaces
            start = i
            while i < n and s[i] == ' ':
                i += 1
            result.append(s[start:i])  # preserve original spaces
        else:
            # accumulate a word (non-space characters)
            start = i
            while i < n and s[i] != ' ':
                i += 1
            word = s[start:i]
            sorted_word = ''.join(sorted(word))
            result.append(sorted_word)
    return ''.join(result)


