def wse_function(l: list):
    """
    wse_function takes a list of integers as an input.
    it returns True if there are three distinct elements in the list that
    sum to zero, and False otherwise.

    >>> wse_function([1, 3, 5, 0])
    False
    >>> wse_function([1, 3, -2, 1])
    True
    >>> wse_function([1, 2, 3, 7])
    False
    >>> wse_function([2, 4, -5, 3, 9, 7])
    True
    >>> wse_function([1])
    False
    """
    n = len(l)
    if n < 3:
        return False

    l_sorted = sorted(l)
    for i in range(n - 2):
        # Avoid duplicates for i
        if i > 0 and l_sorted[i] == l_sorted[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            s = l_sorted[i] + l_sorted[left] + l_sorted[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False


