import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(s):
    """
    Takes a string s and returns a string where each sequence of non-space characters
    (words separated by literal spaces) is replaced by a version with its characters
    sorted in ascending ASCII order. Spaces are preserved exactly in their original
    positions. Other whitespace characters (like tabs, newlines) are treated as part of
    words and get sorted within them.

    For example:
    wse_function('Hi') -> 'Hi'
    wse_function('hello') -> 'ehllo'
    wse_function('Hello World!!!') -> 'Hello !!!Wdlor'
    """
    result = []
    word_chars = []

    for ch in s:
        if ch == ' ':
            if word_chars:
                # Sort the collected word characters and append
                result.append(''.join(sorted(word_chars)))
                word_chars = []
            # Append the space as is
            result.append(ch)
        else:
            # Accumulate non-space characters
            word_chars.append(ch)

    # If last part was a word, append it sorted
    if word_chars:
        result.append(''.join(sorted(word_chars)))

    return ''.join(result)


