def wse_function(lst):
    """
    This function takes a list or tuple of integers. For each entry in the sequence:
    - If its index is a multiple of 3 (including multiples of 12), square the entry.
    - Else if its index is a multiple of 4 but not a multiple of 3, cube the entry.
    - Otherwise, keep the entry unchanged.
