    def digit_sum(n):
        s = str(n)
        if s[0] != '-':
            # positive number or zero: sum digits normally
            return sum(int(ch) for ch in s)
        else:
            # negative number: negate only the first digit after minus, add the rest normally
            # e.g. n = -12 -> digits: '1', '2' -> sum = -1 + 2 = 1
            first_digit = int(s[1])
            rest_digits = s[2:]
            rest_sum = sum(int(ch) for ch in rest_digits) if rest_digits else 0
