def wse_function(s: str, n: int):
    vowels = set('aeiouAEIOU')
    if not s:
        return []
    words = s.split()
    result = []
    for w in words:
        non_vowel_count = sum(1 for ch in w if ch.isalpha() and ch not in vowels)
        if non_vowel_count == n:
            result.append(w)
    return result


def wse_variants(args):
