def wse_function(t):
    """
    Accepts a string t and returns a string where each contiguous sequence of non-space characters
    is replaced by the same characters sorted in ascending character code order,
    while preserving all spaces in their original positions.
    """
    result = []
    i = 0
    n = len(t)
    while i < n:
        if t[i] == ' ':
            # Preserve spaces exactly
            result.append(' ')
            i += 1
        else:
            # Collect a token of non-space characters
            start = i
            while i < n and t[i] != ' ':
                i += 1
            token = t[start:i]
