from typing import *
import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(a, b, n):
    # Extended Euclidean Algorithm to find gcd and one solution (x0, y0) for a*x + b*y = gcd(a,b)
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return gcd, x, y

    # Handle special cases when a or b is zero
    if a == 0 and b == 0:
        if n == 0:
            # Infinite solutions, but we need smallest x >= 0, so x=0,y=0
            return ('x = ', 0, ', y = ', 0)
        else:
            return 'No solution'

    if a == 0:
        # Equation: b*y = n
        if b == 0:
            return 'No solution'  # already handled above, but just in case
        if n % b != 0:
            return 'No solution'
        y = n // b
        if y < 0:
            return 'No solution'
        return ('x = ', 0, ', y = ', y)

    if b == 0:
        # Equation: a*x = n
        if n % a != 0:
            return 'No solution'
        x = n // a
        if x < 0:
            return 'No solution'
        return ('x = ', x, ', y = ', 0)

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % gcd != 0:
        return 'No solution'

    # Scale the initial solution by n // gcd
    scale = n // gcd
    x0 *= scale
    y0 *= scale

    # Adjust signs according to original signs of a and b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # General solution:
    # x = x0 + k * (b // gcd)
    # y = y0 - k * (a // gcd)
    # We want the smallest non-negative x >= 0

    b_div = b // gcd
    a_div = a // gcd

    # Find k such that x >= 0 and x is minimized
    # Solve x0 + k * b_div >= 0  =>  k >= -x0 / b_div
    # Because k is integer, k must be ceiling of (-x0 / b_div) if b_div > 0
    # or floor if b_div < 0

    # We want the smallest x >= 0, so find the minimal k satisfying x >= 0
    from math import ceil, floor

    if b_div > 0:
        k_min = ceil(-x0 / b_div)
    else:
        k_min = floor(-x0 / b_div)

    x_candidate = x0 + k_min * b_div
    y_candidate = y0 - k_min * a_div

    if x_candidate < 0:
        # No non-negative x solution
        return 'No solution'

    # Return the solution in required format
    return ('x = ', x_candidate, ', y = ', y_candidate)


def wse_variants(args):
    orders = list(itertools.permutations(args)) if len(args) <= 4 else [args]
