def wse_function(m: int, n: int) -> int:
    if n == 0 or m == 0:
        return 0
    # dp[length][value] = number of sequences of length `length` ending with `value`
    dp = [ [0] * (m + 1) for _ in range(n + 1) ]

    # Base case: sequences of length 1
    for value in range(1, m + 1):
        dp[1][value] = 1

    for length in range(2, n + 1):
        # To optimize, precompute prefix sums of dp[length-1]
        prefix_sums = [0] * (m + 2)
        for v in range(1, m + 1):
            prefix_sums[v] = prefix_sums[v-1] + dp[length-1][v]

        for value in range(1, m + 1):
            # The previous element must be <= value // 2
            max_prev = value // 2
            if max_prev >= 1:
                dp[length][value] = prefix_sums[max_prev]
            else:
                dp[length][value] = 0

    return sum(dp[n][1:m+1])


