def wse_function(arr, left, right):
    """
    Find the smallest missing non-negative integer in the subarray arr[left:right+1].

    Args:
        arr (list or tuple): The input array.
        left (int): The start index of the subarray (inclusive).
        right (int): The end index of the subarray (inclusive).

    Returns:
        int: The smallest missing non-negative integer in arr[left:right+1].
