import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(arr, low, high):
    if low > high:
        return None
    if low == high:
        return arr[low]

    mid = (low + high) // 2

    # If mid element is greater than the next element, mid is max
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]

    # If mid element is smaller than the previous element, previous is max
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    # If elements at low, mid, and high are equal, search both sides
    if arr[low] == arr[mid] == arr[high]:
        left_max = wse_function(arr, low, mid - 1)
        right_max = wse_function(arr, mid + 1, high)
        candidates = [x for x in (left_max, right_max) if x is not None]
        return max(candidates) if candidates else None

    # If left part is sorted and mid element is greater than left element,
    # max must be in right part
    if arr[low] < arr[mid] or (arr[low] == arr[mid] and arr[mid] > arr[high]):
        return wse_function(arr, mid + 1, high)
    else:
        return wse_function(arr, low, mid - 1)


