from typing import *
import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(a, b, n):
    # Handle special cases where a or b is zero
    if a == 0 and b == 0:
        # Equation reduces to 0 = n
        if n == 0:
            return ('x = ', 0, ', y = ', 0)
        else:
            return 'No solution'
    if a == 0:
        # Equation is b*y = n
        if b != 0 and n % b == 0:
            y = n // b
            if y >= 0:
                return ('x = ', 0, ', y = ', y)
        return 'No solution'
    if b == 0:
        # Equation is a*x = n
        if a != 0 and n % a == 0:
            x = n // a
            if x >= 0:
                return ('x = ', x, ', y = ', 0)
        return 'No solution'

    # For a != 0 and b != 0, search for non-negative integer solutions
    # We try x from 0 upwards until y = (n - a*x)/b is integer and non-negative
    # Stop if a*x > n and a, b > 0 or if a*x < n and a < 0 and b > 0 etc.
    # To avoid infinite loop, we limit x search range reasonably

    # Determine search direction and limit:
    # If a > 0, increasing x makes a*x bigger, so no need to check x > n//a + 1
    # If a < 0, increasing x makes a*x smaller, so we try x up to a reasonable limit
    # We consider x up to max_x to avoid infinite loops

    max_x = 0
    if a > 0:
        max_x = n // a + 1 if n >= 0 else 0
    elif a < 0:
        # If a < 0, to find non-negative x, we can limit x to some large number to avoid infinite loops
        # But better to use a heuristic:
        # Since a*x + b*y = n and y >= 0, a*x <= n
        # Since a < 0, a*x <= n means x >= n/a (which is negative or zero)
        # So we try x from 0 up to some large number, for example 10^6
        max_x = 10**6

    for x in range(max_x + 1):
        rem = n - a * x
        if b == 0:
            # Already handled above, but just in case
            if rem == 0:
                if x >= 0:
                    return ('x = ', x, ', y = ', 0)
                else:
                    continue
        else:
            if rem % b == 0:
                y = rem // b
                if y >= 0:
                    return ('x = ', x, ', y = ', y)

    return 'No solution'


