def wse_function(seq):
    """
    Reconstruct a list from a run-length encoded sequence.
    The input seq is a list or tuple interpreted as pairs of (count, value).
    Each value is repeated count times in the output list.
    If the length of seq is odd, the last element is treated as a value with count 1.

    Examples:
    wse_function([1, 2])       -> [2]
    wse_function([2, 5, 3, 7]) -> [5, 5, 7, 7, 7]
    wse_function([1, 2, 3])    -> [2, 3, 3, 3]
    wse_function([])           -> []
    """
    result = []
    i = 0
    n = len(seq)
    while i < n:
        if i + 1 < n:
            count, value = seq[i], seq[i + 1]
            result.extend([value] * count)
            i += 2
        else:
            # last single value with implicit count 1
            result.append(seq[i])
            i += 1
    return result


