import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(N: int, K: int) -> int:
    if K == 0:
        return 0
    # dp[i][length] = number of sequences of length `length` starting with element i
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: sequences of length 1
    for i in range(1, N + 1):
        dp[i][1] = 1

    for length in range(2, K + 1):
        # To optimize, we can precompute suffix sums to avoid O(N^2)
        suffix_sum = [0] * (N + 2)  # index from 1 to N+1 for convenience
        for i in range(N, 0, -1):
            suffix_sum[i] = suffix_sum[i + 1] + dp[i][length - 1]

        for i in range(1, N + 1):
            start = 2 * i
            if start <= N:
                dp[i][length] = suffix_sum[start]
            else:
                dp[i][length] = 0

    # Total sequences are sum of sequences of length K starting at any element 1..N
    return sum(dp[i][K] for i in range(1, N + 1))


