def wse_function(text):
    """
    Find all substrings of `text` that contain the characters of the internally
    defined sequence in order, possibly with other characters in between.

    The sequence to match is predefined inside this function.

    Returns a list of all such substrings.
    """
    sequence = "abc"  # Example predefined sequence

    results = []
    seq_len = len(sequence)
    text_len = len(text)

    for start in range(text_len):
        if text[start] != sequence[0]:
            continue
        seq_index = 0
        end = start
        # Try to find all sequence characters in order starting at text[start]
        for i in range(start, text_len):
            if text[i] == sequence[seq_index]:
                seq_index += 1
                if seq_index == seq_len:
                    end = i
                    break
        else:
            # Did not find full sequence
            continue
        # Add substring from start to end inclusive
        results.append(text[start:end+1])

    return results


