from typing import *
import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(text: str) -> str:
    """
    Insert spaces before uppercase letters that are immediately preceded by a word character,
    except when the uppercase letters form a consecutive sequence (an acronym).
    Consecutive uppercase letters are treated as a single acronym and are not split.

    Args:
        text (str): The input string.

    Returns:
        str: The adjusted string with spaces inserted as described.
    """
    if not text:
        return text

    result = [text[0]]  # start with first character as is

    i = 1
    length = len(text)

    while i < length:
        c = text[i]
        prev = text[i - 1]

        if c.isupper():
            # Check if prev is a word character (letter, digit, underscore)
            if prev.isalnum() or prev == '_':
                # Check if this uppercase is start of acronym or start of capitalized word
                # Look ahead to see if next char is uppercase (acronym) or not
                # If next char exists and is uppercase, we're inside acronym, no space
                # Else, insert space before this uppercase letter

                # Look ahead char
                next_char = text[i + 1] if (i + 1) < length else None

                if next_char is not None and next_char.isupper():
                    # Inside acronym, no space before this uppercase
                    result.append(c)
                else:
                    # Single uppercase letter starting a capitalized word after a word char
                    result.append(' ')
                    result.append(c)
            else:
                # prev is not a word character, just append
                result.append(c)
        else:
            # lowercase or non-uppercase char, just append
            result.append(c)

        i += 1

    return ''.join(result)


