from typing import *
import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(a: int, b: int, n: int):
    """
    Find non-negative integers x, y such that a*x + b*y = n,
    with the smallest non-negative x possible.
    Return (x, y) if such a solution exists, else None.
    """
    if a == 0 and b == 0:
        # Only solution if n == 0
        return (0, 0) if n == 0 else None
    if a == 0:
        # Equation reduces to b*y = n
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        # Equation reduces to a*x = n
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # We want to solve a*x + b*y = n with x,y >= 0
    # Let d = gcd(a,b)
    from math import gcd
    d = gcd(a, b)
    if n % d != 0:
        return None  # no integer solutions at all

    # Simplify equation dividing by d
    a1, b1, n1 = a // d, b // d, n // d

    # Use Extended Euclidean Algorithm to find one particular solution
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, s, t = extended_gcd(y, x % y)
        return (g, t, s - (x // y) * t)

    _, x0, y0 = extended_gcd(a1, b1)
    x0 *= n1
    y0 *= n1

    # General solution: x = x0 + k*(b1), y = y0 - k*(a1)
    # We want x >= 0 and y >= 0
    # So:
    #   x0 + k*b1 >= 0  =>  k >= -x0/b1  (if b1>0)
    #   y0 - k*a1 >= 0  =>  k <= y0/a1   (if a1>0)
    #
    # Note: a1 and b1 are positive or negative depending on input,
    # but gcd returns positive gcd, so signs of a1,b1 depend on a,b.
    #
    # We must handle signs carefully.

    # To avoid sign confusion, handle positive or negative separately:
    # We'll find the range of k satisfying both constraints.

    # Define helper to get ceil division for float k bounds
    def ceil_div(a, b):
        # ceil(a/b) for integers a,b with b != 0
        return -((-a) // b) if b > 0 else -((-a) // b)

    # Define helper to get floor division for float k bounds
    def floor_div(a, b):
        # floor(a/b) for integers a,b with b != 0
        return a // b if b > 0 else a // b

    # Because b1 and a1 can be negative, we normalize inequalities:
    # For inequality k >= -x0/b1:
    # if b1 > 0: k >= ceil_div(-x0, b1)
    # else: k <= floor_div(-x0, b1)

    # For inequality k <= y0/a1:
    # if a1 > 0: k <= floor_div(y0, a1)
    # else: k >= ceil_div(y0, a1)

    # Compute bounds accordingly
    if b1 > 0:
        k_min = ceil_div(-x0, b1)
    else:
        k_max = floor_div(-x0, b1)

    if a1 > 0:
        k_max_ = floor_div(y0, a1)
    else:
        k_min_ = ceil_div(y0, a1)

    # Combine bounds
    if b1 > 0:
        lower_bound = k_min
    else:
        lower_bound = None
    if a1 > 0:
        upper_bound = k_max_
    else:
        upper_bound = None
    if b1 <= 0:
        upper_bound = k_max
    if a1 <= 0:
        lower_bound = k_min_

    # Now find intersection of bounds
    # If any bound is None, treat as unbounded in that direction
    if lower_bound is None:
        lower_bound = -10**18  # very small number
    if upper_bound is None:
        upper_bound = 10**18  # very large number

    if lower_bound > upper_bound:
        return None  # no k satisfies both

    # Among all k in [lower_bound, upper_bound], choose k that minimizes x = x0 + k*b1
    # Since we want minimal non-negative x, and x increases by b1 per k,
    # if b1 > 0, minimal x is at lowest k
    # if b1 < 0, minimal x is at highest k

    if b1 > 0:
        k_best = lower_bound
    else:
        k_best = upper_bound

    x = x0 + k_best * b1
    y = y0 - k_best * a1

    # Check non-negativity (should be guaranteed by bounds)
    if x < 0 or y < 0:
        return None

    # Return solution scaled back (already scaled)
    return (x, y)


def wse_variants(args):
    orders = list(itertools.permutations(args)) if len(args) <= 4 else [args]
    first = args[0] if args else None
    forms = [args[:i] for i in range(len(args) - 1, 0, -1)] + [(list(args),)]
    if isinstance(first, (list, tuple)):
        forms.append(tuple(first))
    if hasattr(first, "__len__"):
        forms += [(first, len(first), *args[1:]), (*args, len(first))]
    return orders[1:] + forms


def find_solution(*args):
    try:
        return wse_function(*args)
    except Exception as failure:
        for variant in wse_variants(args):
            try:
                return wse_function(*variant)
            except Exception:
                pass
        raise failure

