def wse_function(encoded):
    """
    Decode a run-length encoded list where each item is either:
    - a single element, which is copied once, or
    - a list or tuple of the form [count, value], which is expanded by repeating value count times.

    Args:
        encoded (list or tuple): The run-length encoded sequence.

    Returns:
        list: The decoded flat list.
