def wse_function(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 1
    for v in d.values():
        if isinstance(v, dict):
            # nested dict adds 1 to depth
            child_depth = 1 + wse_function(v)
            if child_depth > max_depth:
                max_depth = child_depth
        elif isinstance(v, (list, tuple)):
            # dictionaries inside lists/tuples do NOT add depth beyond containing dict,
            # but can contribute depth from nested dicts inside them, counted as 1
            for item in v:
                if isinstance(item, dict):
                    # depth from dict inside list/tuple is 1 (no +1 because depth does not increase),
                    # but nested dicts inside it add depth normally
                    # so we compute depth of item and take max between max_depth and 1 + depth inside item - 1,
                    # but since depth inside item includes 1 for item itself, we can take depth(item)
                    # and max_depth compares with that or with 1
                    item_depth = wse_function(item)
                    # The dictionary inside list/tuple does not add a layer beyond the current dict,
                    # so max_depth is max(max_depth, item_depth)
                    if item_depth > max_depth:
                        max_depth = item_depth
                elif isinstance(item, (list, tuple)):
                    # recurse into nested lists/tuples the same way
                    # because they might contain dicts
                    # their dicts count as depth 1 relative to the current dict
                    # so we check dicts inside them similarly
                    def max_depth_in_seq(seq):
                        md = 0
                        for elem in seq:
                            if isinstance(elem, dict):
                                ddep = wse_function(elem)
                                if ddep > md:
                                    md = ddep
                            elif isinstance(elem, (list, tuple)):
                                ddep = max_depth_in_seq(elem)
                                if ddep > md:
                                    md = ddep
                        return md
                    seq_depth = max_depth_in_seq(item)
                    if seq_depth > max_depth:
                        max_depth = seq_depth
    return max_depth


