import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(s):
    """
    Generate all permutations of the input string s, including duplicates,
    in a deterministic order based on the original left-to-right character order.

    Args:
        s (str): The input string.

    Returns:
        List[str]: List of all permutations of s including duplicates,
                   in deterministic order.
    """
    result = []
    chars = list(s)
    n = len(chars)
    used = [False] * n
    path = []

    def backtrack():
        if len(path) == n:
            result.append("".join(path))
            return
        for i in range(n):
            if not used[i]:
                used[i] = True
                path.append(chars[i])
                backtrack()
                path.pop()
                used[i] = False

    backtrack()
    return result


