def wse_function(seq, fmt):
    # Check if fmt contains exactly one substitution slot
    # A substitution slot is an unescaped pair of braces: {}
    # or {0} or any single valid format placeholder.
    # We'll parse fmt with string.Formatter.parse to count slots.
    from string import Formatter

    formatter = Formatter()
    slots = 0
    for _, field_name, _, _ in formatter.parse(fmt):
        if field_name is not None:
            slots += 1
    if slots == 1:
        # Format each element by applying fmt to str(element)
        # According to clarifications, the element should be converted to string
        # and used as the single argument for the format string.
        # We must supply either positional or keyword argument.
        # The format string can have {} or {0}, so use positional
        # Pass str(element) as positional argument 0
        return [fmt.format(str(e)) for e in seq]
    else:
        # No slots or multiple slots: ignore element, return fmt repeated
        return [fmt for _ in seq]


