def wse_function(arr, start, end):
    if not arr or start > end or start < 0 or end >= len(arr):
        return None

    # If the segment is not rotated (sorted ascending), maximum is at end
    if arr[start] < arr[end]:
        return arr[end]

    # Binary search for maximum in rotated sorted array
    while start < end:
        mid = (start + end) // 2
        # If mid element is greater than next element, mid is max
        if mid < end and arr[mid] > arr[mid + 1]:
            return arr[mid]
        # If mid element is less than previous element, previous is max
        if mid > start and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide which half to search next
        if arr[mid] > arr[start]:
            # max is in right half
            start = mid + 1
        else:
            # max is in left half
            end = mid - 1

    return arr[start]


