def wse_function(n):
    # Start with the list of odd numbers beginning at 1
    # We'll generate enough numbers to get at least n lucky numbers.
    # As lucky numbers grow roughly like primes, start with a generous range.
    limit = n * 20  # heuristic to ensure enough numbers to sieve
    numbers = list(range(1, limit * 2, 2))  # odd numbers starting at 1

    idx = 1  # start sieving with the second number in the list (index 1)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
