import math

def wse_function(shape: str, *dimensions) -> float | None:
    """
    Calculate the volume of a specified 3D shape given its dimensions.

    Parameters:
    - shape: a string specifying the shape name (case-insensitive).
    - dimensions: numerical dimensions appropriate for the shape.

    Supported shapes and required dimensions:
    - "sphere": radius (1 number)
    - "cube": side length (1 number)
    - "cylinder": radius, height (2 numbers)
    - "cone": radius, height (2 numbers)
    - "rectangular_prism": length, width, height (3 numbers)
    - "square_pyramid": base_side, height (2 numbers)
    - "ellipsoid": a, b, c (3 numbers)

    Returns:
    - volume as a float if inputs are valid and recognized shape
    - None otherwise
    """
    s = shape.lower()
    if s == "sphere" and len(dimensions) == 1:
        r = dimensions[0]
        return (4/3) * math.pi * r**3
    elif s == "cube" and len(dimensions) == 1:
        a = dimensions[0]
        return a**3
    elif s == "cylinder" and len(dimensions) == 2:
        r, h = dimensions
        return math.pi * r**2 * h
    elif s == "cone" and len(dimensions) == 2:
        r, h = dimensions
        return (1/3) * math.pi * r**2 * h
    elif s == "rectangular_prism" and len(dimensions) == 3:
        l, w, h = dimensions
        return l * w * h
    elif s == "square_pyramid" and len(dimensions) == 2:
        b, h = dimensions
        return (1/3) * (b**2) * h
    elif s == "ellipsoid" and len(dimensions) == 3:
        a, b, c = dimensions
        return (4/3) * math.pi * a * b * c
    else:
        return None


