def wse_function(num: int) -> int:
    s = str(num)
    length = len(s)

    # If all digits are 9, the next palindrome is 10...01 (length+1 digits)
    if all(ch == '9' for ch in s):
        return num + 2  # e.g. 9 -> 11, 99 -> 101, 999 -> 1001

    # Helper to build palindrome from left half and middle (if odd length)
    def build_palindrome(left: str, middle: str) -> int:
        if middle:
            pal = left + middle + left[::-1]
        else:
            pal = left + left[::-1]
        return int(pal)

    half_len = length // 2
    odd_len = (length % 2 != 0)

    left = s[:half_len]
    middle = s[half_len] if odd_len else ''
    right = s[half_len + (1 if odd_len else 0):]

    # Build palindrome from left + middle
    pal = build_palindrome(left, middle)

    if pal > num:
        return pal

    # Increment the middle part
    if odd_len:
        # Increment middle digit
        middle_num = int(middle)
        middle_num += 1
        if middle_num <= 9:
            return build_palindrome(left, str(middle_num))
        else:
            # middle digit overflow, set middle to '0' and increment left
            middle = '0'
            # increment left part
            incremented = str(int(left) + 1).zfill(len(left))
            return build_palindrome(incremented, middle)
    else:
        # No middle, increment left part
        incremented = str(int(left) + 1).zfill(len(left))
        return build_palindrome(incremented, '')


