from typing import *
import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(a, b, n):
    # Extended Euclidean Algorithm to find gcd and coefficients
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - (aa // bb) * y1
            return (g, x, y)

    # Special case: both a and b zero
    if a == 0 and b == 0:
        if n == 0:
            return ('x = ', 0, ', y = ', 0)
        else:
            return "No solution"

    # Special case: a == 0 and b > 0 (per clarification)
    if a == 0:
        if b != 0 and n % b == 0:
            y = n // b
            if y >= 0:
                return ('x = ', 0, ', y = ', y)
            else:
                return "No solution"
        else:
            # May loop indefinitely or no solution (per clarification)
            # Here we just return "No solution" to avoid infinite loop
            return "No solution"

    # Compute gcd and one particular solution (x0, y0)
    g, x0, y0 = extended_gcd(abs(a), abs(b))

    # No solution if gcd does not divide n
    if n % g != 0:
        return "No solution"

    # Scale the solution to n/g
    mult = n // g
    x0 *= mult
    y0 *= mult

    # Fix sign of a and b in solution
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # We want non-negative integer solutions (x,y)
    # General solution:
    # x = x0 + k*(b//g)
    # y = y0 - k*(a//g)
    # Find k so that x >= 0 and y >= 0

    b_div_g = b // g
    a_div_g = a // g

    # To have x >= 0:
    # x0 + k * b_div_g >= 0
    # k >= -x0 / b_div_g if b_div_g > 0
    # k <= -x0 / b_div_g if b_div_g < 0

    # To have y >= 0:
    # y0 - k * a_div_g >= 0
    # k <= y0 / a_div_g if a_div_g > 0
    # k >= y0 / a_div_g if a_div_g < 0

    # We'll find the range of integer k that satisfy both

    import math

    if b_div_g > 0:
        k_min_x = math.ceil(-x0 / b_div_g)
    elif b_div_g < 0:
        k_min_x = math.floor(-x0 / b_div_g)
    else:
        # b_div_g == 0 means b == 0, no special handling per clarification,
        # but division/modulo by zero may occur, so just treat k_min_x as None
        k_min_x = None

    if a_div_g > 0:
        k_max_y = math.floor(y0 / a_div_g)
    elif a_div_g < 0:
        k_max_y = math.ceil(y0 / a_div_g)
    else:
        # a_div_g == 0 means a == 0, already handled above, so no special here
        k_max_y = None

    # Determine the intersection of k intervals for x>=0 and y>=0
    # If b_div_g == 0, x = x0 constant, x0 must be >=0 else no solution
    # If a_div_g == 0, y = y0 constant, y0 must be >=0 else no solution

    possible_ks = []

    if b_div_g == 0 and a_div_g == 0:
        # x = x0, y = y0 constant
        if x0 >= 0 and y0 >= 0:
            return ('x = ', x0, ', y = ', y0)
        else:
            return "No solution"

    elif b_div_g == 0:
        # x = x0 constant, must be >=0
        if x0 < 0:
            return "No solution"
        # y = y0 - k * a_div_g >=0
        # solve for k depending on sign of a_div_g
        if a_div_g > 0:
            # k <= y0 / a_div_g
            k_upper = math.floor(y0 / a_div_g)
            # k can be any integer <= k_upper, try all from -inf to k_upper
            # minimal x is fixed, so minimal x is always x0
            # we want smallest x, so just pick k = k_upper (largest k)
            k = k_upper
            y = y0 - k * a_div_g
            if y >= 0:
                return ('x = ', x0, ', y = ', y)
            else:
                return "No solution"
        else:
            # a_div_g < 0
            # k >= y0 / a_div_g
            k_lower = math.ceil(y0 / a_div_g)
            k = k_lower
            y = y0 - k * a_div_g
            if y >= 0:
                return ('x = ', x0, ', y = ', y)
            else:
                return "No solution"

    elif a_div_g == 0:
        # y = y0 constant, must be >=0
        if y0 < 0:
            return "No solution"
        # x = x0 + k * b_div_g >=0
        # solve for k depending on sign of b_div_g
        if b_div_g > 0:
            # k >= -x0 / b_div_g
            k_lower = math.ceil(-x0 / b_div_g)
            # smallest x at minimal k
            k = k_lower
            x = x0 + k * b_div_g
            if x >= 0:
                return ('x = ', x, ', y = ', y0)
            else:
                return "No solution"
        else:
            # b_div_g < 0
            # k <= -x0 / b_div_g
            k_upper = math.floor(-x0 / b_div_g)
            k = k_upper
            x = x0 + k * b_div_g
            if x >= 0:
                return ('x = ', x, ', y = ', y0)
            else:
                return "No solution"

    else:
        # Both b_div_g and a_div_g nonzero
        # We want k in the intersection of intervals:
        # if b_div_g > 0: k >= k_min_x else k <= k_min_x
        # if a_div_g > 0: k <= k_max_y else k >= k_max_y

        if b_div_g > 0 and a_div_g > 0:
            # k >= k_min_x and k <= k_max_y
            if k_min_x > k_max_y:
                return "No solution"
            # Among solutions in [k_min_x, k_max_y], pick minimal x:
            # x = x0 + k * b_div_g; b_div_g > 0, so minimal x at minimal k
            k = k_min_x
            x = x0 + k * b_div_g
            y = y0 - k * a_div_g
            if x >= 0 and y >= 0:
                return ('x = ', x, ', y = ', y)
            else:
                return "No solution"

        elif b_div_g > 0 and a_div_g < 0:
            # k >= k_min_x and k >= k_max_y
            k_lower = max(k_min_x, k_max_y)
            k = k_lower
            x = x0 + k * b_div_g
            y = y0 - k * a_div_g
            if x >= 0 and y >= 0:
                return ('x = ', x, ', y = ', y)
            else:
                return "No solution"

        elif b_div_g < 0 and a_div_g > 0:
            # k <= k_min_x and k <= k_max_y
            k_upper = min(k_min_x, k_max_y)
            k = k_upper
            x = x0 + k * b_div_g
            y = y0 - k * a_div_g
            if x >= 0 and y >= 0:
                return ('x = ', x, ', y = ', y)
            else:
                return "No solution"

        else:  # b_div_g < 0 and a_div_g < 0
            # k <= k_min_x and k >= k_max_y
            if k_max_y > k_min_x:
                return "No solution"
            # k in [k_max_y, k_min_x]
            # b_div_g < 0, x = x0 + k*b_div_g decreases as k increases
            # minimal x at maximal k = k_min_x
            k = k_min_x
            x = x0 + k * b_div_g
            y = y0 - k * a_div_g
            if x >= 0 and y >= 0:
                return ('x = ', x, ', y = ', y)
            else:
                return "No solution"


