from typing import *
import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(m: int, n: int) -> int:
    """
    Count the number of length-n sequences from 1 to m (inclusive)
    that are nondecreasing and satisfy that each element is at least
    twice the previous one.

    Parameters:
    - m (int): The maximum value in the sequence (minimum is 1).
    - n (int): The length of the sequence.

    Returns:
    - int: The total number of sequences meeting the conditions.
    """
    if n == 0:
        # There is exactly one sequence of length 0: the empty sequence
        return 1
    if m < 1 or n < 0:
        # If m less than 1 or n negative, no valid sequences
        return 0

    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(pos: int, prev: int) -> int:
        """
        Count sequences of length (n - pos) where the previous element is prev,
        with the constraints:
        - next element >= prev (nondecreasing)
        - next element >= 2 * prev (at least twice the previous)
        """
        if pos == n:
            return 1

        total = 0
        # The next element must be at least max(prev, 2*prev)
        # But since sequence is nondecreasing, next >= prev
        # and next >= 2*prev, so next >= max(prev, 2*prev)
        # This simplifies to next >= 2*prev (because 2*prev >= prev for prev>=1)
        # For the first element (pos == 0), prev can be 0, so next >= max(1, 2*0) == 1
        start = max(1, 2 * prev)
        for next_val in range(start, m + 1):
            total += count_sequences(pos + 1, next_val)
        return total

    # Start with prev = 0 to allow first element >= 1
    return count_sequences(0, 0)


