import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(arr, left, right):
    """
    Find the smallest missing non-negative integer in the subarray arr[left:right+1].
    Assumes the array is 0-indexed and that when no value is missing up to position i,
    arr[i] == i.

    Parameters:
    arr (list or tuple): Input array.
    left (int): Start index of the subarray (inclusive).
    right (int): End index of the subarray (inclusive).

    Returns:
    int: The smallest missing non-negative integer within arr[left:right+1].
    """
    # Extract the relevant subarray slice
    sub = arr[left:right+1]

    n = len(sub)
    for i in range(n):
        # Mark elements which are in the range [0, n-1]
        while 0 <= sub[i] < n and sub[i] != sub[sub[i]]:
            # Swap sub[i] and sub[sub[i]] to place elements in their "correct" index
            target = sub[i]
            sub[i], sub[target] = sub[target], sub[i]

    # After rearrangement, the first index i where sub[i] != i is the missing integer
    for i in range(n):
        if sub[i] != i:
            return i
    # If all indices match, the missing integer is n
    return n


