def wse_function(s: str) -> str:
    if not s:
        return s

    result = [s[0]]
    length = len(s)

    for i in range(1, length):
        c = s[i]
        prev = s[i - 1]
        next_char = s[i + 1] if i + 1 < length else ''

        if c.isupper():
            # Insert space if previous char is a word char and:
            # not inside a sequence of uppercase letters (i.e. next char not uppercase)
            # or if previous char is lowercase or digit (part of previous word)
            # The condition to NOT insert space is if c is part of a consecutive uppercase sequence.
            if prev.isalnum() and not (prev.isupper() and next_char.isupper()):
                result.append(' ')
        result.append(c)

    return ''.join(result)


