def wse_function(n):
    if n <= 0:
        return []
    # Start with the sequence of odd numbers starting from 1
    nums = list(range(1, 2 * n * 10, 2))  # oversize list to ensure enough lucky numbers
    idx = 1  # start sieving with the second element (index 1)
    while idx < len(nums):
        step = nums[idx]
        if step > len(nums):
            break
        # Remove every step-th element from nums, counting from 1
        # That means keep elements whose (position+1) % step != 0
        nums = [num for i, num in enumerate(nums) if (i + 1) % step != 0]
