from typing import *
import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(num: int) -> int:
    s = str(num)
    length = len(s)

    # If all digits are 9, the next palindrome is 10...01 (length+1 digits)
    if all(ch == '9' for ch in s):
        return num + 2  # e.g. 9->11, 99->101, 999->1001

    # Convert string to list for easier manipulation
    digits = list(s)

    # Function to check if palindrome
    def is_palindrome(arr):
        return arr == arr[::-1]

    # Generate palindrome by mirroring left to right
    def make_palindrome(arr):
        n = len(arr)
        half = n // 2
        for i in range(half):
            arr[-(i+1)] = arr[i]
        return arr

    # Compare two lists of digits
    def compare_lists(a, b):
        for x, y in zip(a, b):
            if x < y:
                return -1
            elif x > y:
                return 1
        return 0

    # Increment the middle part and adjust palindrome
    def increment_middle(arr):
        n = len(arr)
        mid = n // 2
        left_end = mid - 1
        right_start = mid + 1 if n % 2 else mid

        # Increment middle digit(s)
        if n % 2 == 1:
            # Odd length
            if arr[mid] != '9':
                arr[mid] = str(int(arr[mid]) + 1)
                return arr
            else:
                arr[mid] = '0'
                carry = 1
        else:
            carry = 1

        # Propagate carry to the left half
        i = left_end
        while i >= 0 and carry:
            if arr[i] == '9':
                arr[i] = '0'
                carry = 1
            else:
                arr[i] = str(int(arr[i]) + 1)
                carry = 0
            i -= 1

        # If carry is still 1, means we had all 9's in left half
        # In that case, the number length increases by 1,
        # but this is handled by the initial all 9 check.

        # Mirror left half to right half
        for j in range(left_end + 1):
            arr[-(j + 1)] = arr[j]

        return arr

    # Step 1: Make palindrome by mirroring left to right
    palindrome = make_palindrome(digits[:])

    # Step 2: If palindrome > num, return it
    if compare_lists(palindrome, digits) == 1:
        return int(''.join(palindrome))

    # Step 3: Otherwise, increment the middle part and mirror again
    palindrome = increment_middle(palindrome)
    return int(''.join(palindrome))


