import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(a: int, b: int, n: int):
    # Handle the trivial case when n=0
    if n == 0:
        # We want nonnegative x,y with a*0 + b*0 = 0
        # Return (0,0) as per clarifications
        return (0, 0)

    # Handle cases where a and/or b = 0 separately
    if a == 0 and b == 0:
        # then equation is 0 = n, no solution unless n == 0 (handled above)
        return None
    if a == 0:
        # Equation: b*y = n
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        # Equation: a*x = n
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # General case: both a and b are nonzero
    # We try x from 0 upwards to find the smallest x with y nonnegative integer
    # Stop when a*x > n since y would be negative for x beyond that

    # To avoid infinite loop if a or b negative, use absolute values and consider signs carefully
    # But problem does not restrict signs, so handle accordingly

    # If a > 0, x can go from 0 to n//a
    # If a < 0, since x≥0, a*x ≤ 0, so a*x + b*y = n means b*y = n - a*x ≥ n
    # but since x≥0 and a<0, a*x ≤0, so n - a*x ≥ n, so y might be negative or positive depending on b and n.
    # To keep it simple, we try x from 0 upwards until a*x surpasses n if a>0, else go up to some reasonable bound.

    # To guarantee termination, set a max iteration bound:
    # If a>0: max_x = n//a
    # If a<0: since a*x ≤0, n - a*x ≥ n, y = (n - a*x)/b must be integer and ≥0
    # But since x≥0 and a<0, a*x ≤0, so n - a*x ≥ n, so y≥ n/b for b>0 or y≤ n/b for b<0

    # To avoid complex sign checks, we will try x from 0 to max_x where max_x = max(0, n//a) if a>0 else a large number (e.g. 10**7)
    # but large number is not efficient. Instead, we can try x up to a point where y can be nonnegative integer.

    # Instead, we can try x from 0 up to n if a>0, or up to some reasonable max (e.g. 10**7) if a<0.
    # Or we can try x up to a limit, but since problem is theoretical, we do:

    # To handle negative a or b, let's try all x from 0 to n if n>=0 else no solutions because x,y≥0 and a,b,n integers.

    # If n < 0, since x,y≥0 and a*x + b*y = n < 0, no solution because a*x + b*y ≥ 0 if a,b≥0
    # But a,b can be negative, so we try anyway.

    # So to be safe, try x from 0 up to max_x, where max_x is n if n≥0 else 0 (no solutions)
    # To limit iterations, if n≥0, max_x = n if a>0 else max_x = n*abs(b) (some large number)
    # To make a principled approach, we can try x from 0 to n if n≥0 else return None

    if n < 0:
        # Since x,y≥0 and a,b,n integers, test if any solution possible
        # We try anyway up to 0, so no solution
        return None

    max_x = n if a > 0 else n * abs(b)
    # to avoid huge loops if b very large and a<0, limit max_x to some large value
    max_x = min(max_x, 10**7)

    for x in range(max_x + 1):
        ax = a * x
        rem = n - ax
        if rem < 0:
            # Since y≥0, and b*y = rem < 0, no y≥0 solution here
            continue
        if b == 0:
            # Already handled above, but if reached here, no solution
            continue
        if rem % b == 0:
            y = rem // b
            if y >= 0:
                return (x, y)

    return None


