import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(n: int, m: int) -> int:
    if n == 1:
        # For sequences of length 1, any value from 1 to m is valid
        return m
    # dp[i][x] = number of sequences of length i ending with x
    # To reduce memory, we keep only dp for previous length
    prev_dp = [1] * (m + 1)  # sequences of length 1 ending with x: 1 for all x in [1..m]

    for length in range(2, n + 1):
        curr_dp = [0] * (m + 1)
        # prefix sums for prev_dp to optimize range sum queries
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + prev_dp[x]
        prefix[m + 1] = prefix[m]

        for x in range(1, m + 1):
            # For current element x, previous element p must satisfy:
            # p <= x // 2 (since x >= 2 * p)
            max_prev = x // 2
            if max_prev >= 1:
                curr_dp[x] = prefix[max_prev]  # sum of prev_dp[p] for p in [1..max_prev]
            else:
                curr_dp[x] = 0
        prev_dp = curr_dp

    return sum(prev_dp[1:])  # sum over all sequences of length n ending with any x in [1..m]


def wse_variants(args):
    orders = list(itertools.permutations(args)) if len(args) <= 4 else [args]
    first = args[0] if args else None
    forms = [args[:i] for i in range(len(args) - 1, 0, -1)] + [(list(args),)]
    if isinstance(first, (list, tuple)):
        forms.append(tuple(first))
    if hasattr(first, "__len__"):
        forms += [(first, len(first), *args[1:]), (*args, len(first))]
    return orders[1:] + forms


