def wse_function(A, start, end):
    # If the subarray is empty, the smallest missing is start
    if start > end:
        return start
    # If the first element is greater than start, then start is missing
    if A[start] > start:
        return start
    # Binary search for the smallest index i where A[i] != i
    low, high = start, end
    while low <= high:
        mid = (low + high) // 2
        if A[mid] == mid:
            low = mid + 1
        else:
            high = mid - 1
    # low is the smallest index where A[low] != low (or low == end+1 if none)
    return low


