def wse_function(arr, low, high):
    if low > high:
        return None  # invalid indices or empty subarray
    if low == high:
        return arr[low]
    # If array is not rotated (sorted ascending), max is at high
    if arr[low] < arr[high]:
        return arr[high]

    mid = (low + high) // 2

    # Check if mid element is greater than its next element
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]
    # Check if mid element is smaller than its previous element
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    # Decide which half to search next
    if arr[mid] >= arr[low]:
        # Left part is sorted, max must be in right part
        return wse_function(arr, mid + 1, high)
    else:
        # Right part is sorted, max must be in left part
        return wse_function(arr, low, mid - 1)


