import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(n):
    if n <= 0:
        return []
    # Start with odd numbers only (1, 3, 5, 7, ...) enough to get n lucky numbers
    # Start with a buffer longer than n to allow for sieving
    # The lucky number sieve can eliminate some numbers, so start with a larger list
    limit = n * 20  # heuristic multiplier to ensure enough numbers remain after sieving
    numbers = list(range(1, limit * 2, 2))  # odd numbers starting from 1

    idx = 1  # start sieving with the second number in the list (index 1)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list (1-based indexing)
        # Because indexing is 0-based, remove elements at indices that are multiples of step, 
        # but skip the element at idx itself
        numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
        idx += 1
        if len(numbers) >= n:
            # Continue until at least n lucky numbers remain
            continue
        else:
            # If the list got too short, increase limit and restart sieve
            limit *= 2
            numbers = list(range(1, limit * 2, 2))
            idx = 1

    return numbers[:n]


