def wse_function(a: int, b: int) -> int:
    if a > b:
        # If a > b, factorial(b)/factorial(a) is not defined as factorial(a) > factorial(b),
        # but we return 0 as last digit by convention (no division).
        return 0
    if a == b:
        # factorial(b)/factorial(a) = 1 when a == b
        return 1
    product = 1
    for i in range(a + 1, b + 1):
        product *= i
        product %= 10  # keep only last digit to avoid large numbers
        if product == 0:
            # Once last digit is zero, it stays zero
            break
    return product


