import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(num: int) -> int:
    s = str(num)
    length = len(s)

    # Handle single digit numbers quickly
    if length == 1:
        return num + 1 if num < 9 else 11

    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    # If all digits are 9, next palindrome is 10..01 (length+1 digits)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Split the number into two halves
    mid = length // 2
    left = s[:mid]
    middle = s[mid] if length % 2 else ''
    right = s[mid + 1:] if length % 2 else s[mid:]

    # Form a palindrome by mirroring left + middle to right
    if length % 2:
        palindrome = left + middle + left[::-1]
    else:
        palindrome = left + left[::-1]

    if int(palindrome) > num:
        return int(palindrome)

    # Increment the middle part and form new palindrome
    if length % 2:
        # Increment the middle digit and handle carry
        middle_num = int(middle)
        left_num = int(left) if left else 0

        if middle_num < 9:
            middle_num += 1
            palindrome = left + str(middle_num) + left[::-1]
            return int(palindrome)
        else:
            # middle digit is 9, set it to 0 and increment left part
            middle_num = 0
            left_num += 1
            left_str = str(left_num).rjust(len(left), '0')
            palindrome = left_str + str(middle_num) + left_str[::-1]
            return int(palindrome)
    else:
        # Even length: increment left part and mirror
        left_num = int(left)
        left_num += 1
        left_str = str(left_num).rjust(len(left), '0')
        palindrome = left_str + left_str[::-1]
        return int(palindrome)


