from typing import *
import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        gcd, s1, t1 = extended_gcd(y, x % y)
        s = t1
        t = s1 - (x // y) * t1
        return gcd, s, t

    # Handle special cases when a or b is zero
    if a == 0 and b == 0:
        return 'No solution' if n != 0 else ('x = ', 0, ', y = ', 0)

    if a == 0:
        if b == 0:
            return 'No solution'
        if n % b == 0:
            y = n // b
            if 0 >= 0:
                return ('x = ', 0, ', y = ', y)
            else:
                return 'No solution'
        else:
            return 'No solution'

    if b == 0:
        if n % a == 0:
            x = n // a
            if x >= 0:
                return ('x = ', x, ', y = ', 0)
            else:
                return 'No solution'
        else:
            return 'No solution'

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % gcd != 0:
        return 'No solution'

    # scale the solution to n
    x0 *= n // gcd
    y0 *= n // gcd

    # adjust signs according to original a and b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # General solution:
    # x = x0 + k*(b/gcd)
    # y = y0 - k*(a/gcd)
    # We want to find k so that x >= 0 and return the first such solution

    b_div = b // gcd
    a_div = a // gcd

    # If b_div == 0, then no adjustment possible on x by k, check x0 directly
    if b_div == 0:
        if x0 >= 0:
            return ('x = ', x0, ', y = ', y0)
        else:
            return 'No solution'

    # Find k such that x0 + k*b_div >= 0
    # k >= (-x0) / b_div if b_div > 0
    # k <= (-x0) / b_div if b_div < 0
    if b_div > 0:
        k = (-x0 + b_div - 1) // b_div  # ceil division for positive b_div
    else:
        k = (-x0) // b_div  # floor division for negative b_div

    x = x0 + k * b_div
    y = y0 - k * a_div

    if x >= 0:
        return ('x = ', x, ', y = ', y)
    else:
        return 'No solution'


