import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(m, n):
    # dp[i][x]: number of sequences of length i ending with x
    # Elements are in [1..m]
    # For i=1, dp[1][x] = 1 for all x in [1..m]
    if n == 0 or m == 0:
        return 0
    if n == 1:
        return m

    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # To optimize, precompute prefix sums of dp
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp[x]

        for x in range(1, m + 1):
            # previous element y must satisfy y * 2 <= x => y <= x // 2
            max_prev = x // 2
            if max_prev >= 1:
                new_dp[x] = prefix[max_prev]
            else:
                new_dp[x] = 0
        dp = new_dp

    return sum(dp[1:])


