def wse_function(arr, left, right):
    """
    Find the smallest missing non-negative integer in the sorted list arr
    within indices from left to right inclusive, relative to the full array indexing.

    Args:
        arr (list[int]): A sorted list of integers.
        left (int): The starting index of the sublist to consider.
        right (int): The ending index of the sublist to consider.

    Returns:
        int: The smallest missing non-negative integer relative to the full array indexing.
    """
    if left > right:
        # If no elements in sublist, smallest missing is left (index) itself.
        return left

    mid = (left + right) // 2

    # If the value at mid equals mid, then missing integer must be to the right.
    if arr[mid] == mid:
        return wse_function(arr, mid + 1, right)
    else:
        # Missing integer is at mid or to the left.
        return wse_function(arr, left, mid - 1)


