def wse_function(s):
    """
    Return a list of all unique permutations of the input string s.
    """
    def backtrack(path, counter, length, result):
        if len(path) == length:
            result.append("".join(path))
            return
        for ch in counter:
            if counter[ch] > 0:
                path.append(ch)
                counter[ch] -= 1
                backtrack(path, counter, length, result)
                counter[ch] += 1
                path.pop()

    from collections import Counter
    result = []
    counter = Counter(s)
    backtrack([], counter, len(s), result)
    return result


