def wse_function(arr, low, high):
    if low > high:
        return None
    # If subrange has one element
    if low == high:
        return arr[low]

    # While subrange length > 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            # Maximum must be in right half
            low = mid + 1
        elif arr[mid] < arr[high]:
            # Maximum must be in left half including mid
            high = mid
        else:
            # arr[mid] == arr[high], cannot determine side, reduce high by one
            high -= 1

    # low now points to the smallest element (pivot),
    # maximum is element just before pivot in circular order
    max_index = low - 1 if low > 0 else len(arr) - 1
    if max_index < low or max_index < 0 or max_index >= len(arr):
        # Defensive fallback: find max by linear scan in given range if indices are invalid
        return max(arr[low:high+1])
    return arr[max_index]


