    if n <= 0:
        return []
    # Start with a list long enough to generate n lucky numbers
    # Since lucky numbers thin out, start with an estimate and increase if needed
    # Start with some length, we can increase if result is too short
    length = max(10, n * 10)

    while True:
        numbers = list(range(1, length + 1))
        idx = 1  # index in numbers list, starting with second element which is 2 (the first lucky number after 1)
        while idx < len(numbers):
            step = numbers[idx]
            if step > len(numbers):
