            # Remove every step-th element starting from index step-1, zero-based
            # Because counting starts at 1, step-th means remove indices step-1, 2*step-1, ...
            del numbers[step-1::step]
            idx += 1
        if len(numbers) >= n:
            return numbers[:n]
        length *= 2


