def wse_function(lst):
    # If any sublist is empty, return 0 immediately
    for sub in lst:
        if not sub:
            return 0

    unique_sublists = set(tuple(sub) for sub in lst)
    required_count = len(unique_sublists)
    if required_count == 0:
        return 0  # empty input list

    count_map = {}
    formed = 0
    left = 0
    min_len = float('inf')

    for right, sub in enumerate(lst):
        tsub = tuple(sub)
        count_map[tsub] = count_map.get(tsub, 0) + 1
        if count_map[tsub] == 1:
            formed += 1

        while formed == required_count:
            current_len = right - left + 1
            if current_len < min_len:
                min_len = current_len

            left_tsub = tuple(lst[left])
            count_map[left_tsub] -= 1
            if count_map[left_tsub] == 0:
                formed -= 1
            left += 1

    return min_len if min_len != float('inf') else 0


