from typing import *
import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all digits are '9'
    if all(ch == '9' for ch in s):
        # Next palindrome after 999...9 is 100...001 with length+1 digits
        return num + 2

    # Convert the number to a list of digits for easier manipulation
    digits = list(map(int, s))

    # Construct a palindrome by mirroring the left half to the right
    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[-2::-1]
        else:
            return left + left[::-1]

    # Check if a palindrome constructed from left half is > num
    def palindrome_from_left(left, odd_length):
        p_str = make_palindrome(left, odd_length)
        return int(''.join(map(str, p_str)))

    mid = length // 2
    odd_length = (length % 2) == 1

    # Left half digits
    left = digits[:mid + (1 if odd_length else 0)]

    # Construct palindrome from left half
    p = palindrome_from_left(left, odd_length)

    if p > num:
        return p

    # Need to increment the middle part and then mirror again
    # Convert left part to int, increment, then reconstruct palindrome
    left_num = int(''.join(map(str, left)))
    left_num += 1
    left_str = str(left_num)

    # If increment caused length increase (e.g. 999 -> 1000)
    if len(left_str) > len(left):
        # This means the palindrome length increases by 1 or 2 digits,
        # e.g. 999 -> 1001, 9999 -> 10001
        # So next palindrome is 1 followed by zeros and ending with 1
        return int('1' + ('0' * (length - 1)) + '1')

    # Otherwise construct palindrome normally
    left = list(map(int, left_str))
    p = palindrome_from_left(left, odd_length)
    return p


