from typing import *
import bisect, collections, copy, datetime, decimal, fractions, functools, heapq, itertools, json, math, operator, random, re, statistics, string, sys

def wse_function(a, b, n):
    # Extended Euclidean algorithm to find gcd and coefficients x0, y0
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        gcd, x1, y1 = extended_gcd(y, x % y)
        return gcd, y1, x1 - (x // y) * y1

    # Handle the trivial cases
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else "No solution"
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return "No solution"
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return "No solution"

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % gcd != 0:
        return "No solution"

    # Scale the initial solution to the actual equation
    x0 *= n // gcd
    y0 *= n // gcd

    # Adjust signs if a or b were negative
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # The general solution is:
    # x = x0 + k * (b // gcd)
    # y = y0 - k * (a // gcd)

    # We want to find k such that x >= 0 and minimal x starting from 0
    b_div = b // gcd
    a_div = a // gcd

    # If b_div == 0, then x = x0 for all k, so check if x0 >= 0
    if b_div == 0:
        if x0 >= 0:
            return (x0, y0)
        else:
            return "No solution"

    # Find k to make x >= 0:
    # x0 + k*b_div >= 0
    # k >= -x0 / b_div if b_div > 0
    # k <= -x0 / b_div if b_div < 0

    if b_div > 0:
        k_min = (-x0 + b_div - 1) // b_div  # ceil division for negative x0
    else:
        k_min = (-x0) // b_div  # floor division when b_div < 0

    # Because we want the first valid solution with x >= 0 starting from x=0,
    # choose k = k_min

    x = x0 + k_min * b_div
    y = y0 - k_min * a_div

    if x < 0:
        return "No solution"
    return (x, y)


