def wse_function(m, n):
    # dp[i][x]: number of sequences of length i ending with element x
    # Initialize dp for sequences of length 1: every number from 1 to m can start a sequence
    dp = [1] * (m + 1)  # 1-based indexing, dp[x] for length 1 sequences

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # For each possible next element x, sum all dp[y] where y <= x//2
        # because next element x >= 2 * previous element y => y <= x//2
        # To do this efficiently, use prefix sums of dp
        prefix_sum = [0] * (m + 1)
        for i in range(1, m + 1):
            prefix_sum[i] = prefix_sum[i - 1] + dp[i]

        for x in range(1, m + 1):
            limit = x // 2
            if limit >= 1:
                new_dp[x] = prefix_sum[limit]
            else:
                new_dp[x] = 0
        dp = new_dp

    return sum(dp[1:]) if n > 0 else 0


