def wse_function(s):
    def backtrack(path, used):
        if len(path) == len(s):
            result.add("".join(path))
            return
        for i in range(len(s)):
            if used[i]:
                continue
            used[i] = True
            path.append(s[i])
            backtrack(path, used)
            path.pop()
            used[i] = False

    result = set()
    used = [False] * len(s)
    backtrack([], used)
    return list(result)


