def wse_function(arr, low, high):
    if low > high:
        return None
    if low == high:
        return arr[low]
    # If subarray is already sorted (no rotation)
    if arr[low] < arr[high]:
        return arr[high]
    mid = (low + high) // 2
    # Check if mid is maximum
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]
    # Check if mid-1 is maximum
    if mid > low and arr[mid - 1] > arr[mid]:
        return arr[mid - 1]
    # Decide whether to go left or right
    if arr[mid] > arr[low]:
        return wse_function(arr, mid + 1, high)
    else:
        return wse_function(arr, low, mid - 1)


